import{d as g,C as t,o as m,c,j as a,a as s,E as n,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第五十二章","description":"从知子守母到塞兑守柔，理解得本知末、用光归明与袭常。","frontmatter":{"title":"道德经第五十二章","description":"从知子守母到塞兑守柔，理解得本知末、用光归明与袭常。","category":"guide","aliases":["道德经第五十二章","老子第五十二章","dao de jing chapter 52"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-52.md","filePath":"daoism/dao-de-jing/chapter-52.md","lastUpdated":1794189804000}'),x={name:"daoism/dao-de-jing/chapter-52.md"},_=g({...x,setup(b){const o=[{id:"mother-and-offspring",label:"天下有始",showLabel:!0,sentences:[["天下有始，以为天下",{text:"母",glossary:"mu"},"。既得其",{text:"母",glossary:"mu"},"，以知其",{text:"子",glossary:"zi"},"。"]],note:["【白话】天下有一个所由始的根本，可以把它看作天下之母。既已把握这母，便可以由它认识由此而出的子、具体的事物。","【王弼注择要】「母，本也。子，末也。」注继而说「得本以知末，不舍本以逐末也」，使母子之喻落在本末关系。","【读法】母不是另一个有形的造物者，子也不限于某一类生物。所据录文作既知其母、复知其子，本站保留既得其母、以知其子，不混作逐字同本。"]},{id:"returning-to-the-root",label:"复守其母",showLabel:!0,sentences:[["既知其",{text:"子",glossary:"zi"},"，复守其",{text:"母",glossary:"mu"},"，",{text:"没身",glossary:"moshen"},"不",{text:"殆",glossary:"dai"},"。"]],note:["【白话】已经认识了由根本而出的事物，仍回过来守住所由的根本，这样才可终身不因舍本逐末而陷入危殆。","【读法】承前段王注，知末之后并不弃末，而是不以追逐枝末代替根本。没身取终身义，不殆是章内守本的理想判断，不作免除全部现实危险的保证。","【校读】所据电子录文此处作没其不殆，本站保留没身不殆；录文难读字样在此列出，不擅改后作为一致证据。"]},{id:"closing-the-openings",label:"塞其兑，闭其门",showLabel:!0,sentences:[[{text:"塞",glossary:"se"},"其",{text:"兑",glossary:"dui"},"，闭其门，终身不",{text:"勤",glossary:"qin"},"。"]],note:["【白话】堵住欲求向外生发的孔窍，收住逐欲出入的门户，便不至于终身劳倦于无尽的事求。","【王弼注择要】「兑，事欲之所由生；门，事欲之所由从也。」终身不勤下注以「无事永逸」说明不自造繁劳。","【读法】兑在此取孔窍、出口的取象，不直接套用易经兑卦；勤为劳倦，与第四十一章勤勉实践分义。塞兑闭门不是要求取消感官、停止必要沟通。"]},{id:"multiplying-affairs",label:"开其兑，济其事",showLabel:!0,sentences:[["开其",{text:"兑",glossary:"dui"},"，",{text:"济",glossary:"ji"},"其事，终身不救。"]],note:["【白话】反过来，任欲求的出口敞开，不断助长逐求的事务，就会终身难以补救。问题在枝末事务被推动，根本却没有被追问。","【王弼注择要】「不问其原而济其事，故虽终身不救。」注点明济事而不问原，是本句的重心。","【读法】济在此取助成、推进义，不直接解释成救济他人。与前段相对，反省的是无尽逐欲，不是反对一切事务处理。"]},{id:"smallness-and-softness",label:"见小曰明，守柔曰强",showLabel:!0,sentences:[[{text:"见小",glossary:"jianxiao"},"曰",{text:"明",glossary:"ming"},"，",{text:"守柔",glossary:"shourou"},"曰",{text:"强",glossary:"qiang"},"。"]],note:["【白话】能看见细小、尚未显大的关键，叫作明；能守住柔顺而不逞强，才叫作真正的强健。","【王弼注择要】「见大不明，见小乃明。守强不强，守柔乃强也。」注反转只看宏大、只靠刚强的尺度。","【读法】小在本章连治理的关键、细微之处理解，不只指体积小。强读 qiáng，取强健之义；守柔不是失去判断和承担的能力。"]},{id:"light-and-returning-clarity",label:"用其光，复归其明",showLabel:!0,sentences:[["用其光，复归其",{text:"明",glossary:"ming"},"，无",{text:"遗",glossary:"yi"},"身",{text:"殃",glossary:"yang"},"，是为",{text:"袭常",glossary:"xichang"},"。"]],note:["【白话】运用光明来帮助人去除迷惑，又返回不炫示、不过度察人的明，不给自身留下灾殃，这叫承守常道。","【王弼注择要】用其光下注「显道以去民迷」；复归其明下注「不明察也」；录文末句习常下注「道之常也」。","【读法】本站作是为袭常，录文作是谓习常；袭常在本页暂取承守常道，不把袭与习强定为同一字训。用光而归明不是隐去应当说明的事实，而是去迷而不以窥察控制自居。"]}],r=[{id:"mu",term:"母",sense:1},{id:"zi",term:"子",sense:1},{id:"moshen",term:"没身",sense:1},{id:"dai",term:"殆",sense:1},{id:"se",term:"塞",sense:1},{id:"dui",term:"兑",sense:1},{id:"qin",term:"勤",sense:1},{id:"ji",term:"济",sense:1},{id:"jianxiao",term:"见小",sense:1},{id:"ming",term:"明",sense:2},{id:"shourou",term:"守柔",sense:1},{id:"qiang",term:"强",sense:2,pinyin:"qiáng"},{id:"yi",term:"遗",sense:1},{id:"yang",term:"殃",sense:1},{id:"xichang",term:"袭常",sense:1}];return(p,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十二章",tabindex:"-1"},[s("道德经第五十二章 "),a("a",{class:"header-anchor",href:"#道德经第五十二章","aria-label":'Permalink to "道德经第五十二章"'},"​")],-1)),n(i,{title:"知其子之后，为什么还要复守其母",summary:"本章以母子说根本与枝末，再用开闭之门、细小与柔弱、光与明层层展开。王弼以得本知末而不舍本逐末贯通；重点是明白事物之后仍守其所由，而非拒绝接触万事。",points:[{label:"先读",text:"母与子依王弼作本与末，不把知子和守母理解为只能二选一。"},{label:"再辨",text:"塞兑、闭门针对欲求生发的门户，开兑济事则写逐事而不问根本。"},{label:"后看",text:"用光并归明：帮助人去迷，却不以明察搜求为能，结尾连到常道。"}],hint:"塞读 sè，兑读 duì，勤取劳倦义；强在守柔曰强中读 qiáng，没身的没读 mò，殃读 yāng。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:o,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"既知其子，复守其母，没身不殆。",tone:"知末而不舍本",guide:"认识具体事物之后，仍问它们依什么得以成立。"},{text:"塞其兑，闭其门，终身不勤。",tone:"节制逐欲的门户",guide:"从事欲所由生、所由从解释开闭，不将它读成封闭全部感官。"},{text:"用其光，复归其明，无遗身殃，是为袭常。",tone:"去迷而不以察人为能",guide:"先运用光，再归于明，辨清本站袭常与录文习常。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=u('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-母子之喻怎样贯通后面的门与光" tabindex="-1">象：母子之喻怎样贯通后面的门与光？ <a class="header-anchor" href="#象-母子之喻怎样贯通后面的门与光" aria-label="Permalink to &quot;象：母子之喻怎样贯通后面的门与光？&quot;">​</a></h3><p>母子先说本末，开闭之门再问欲求从哪里生发，用光归明则问认识与行动是否仍守其所由。几组取象都围绕知末而不逐末展开。</p><h3 id="理-为什么知得更多还需要复守其母" tabindex="-1">理：为什么知得更多还需要复守其母？ <a class="header-anchor" href="#理-为什么知得更多还需要复守其母" aria-label="Permalink to &quot;理：为什么知得更多还需要复守其母？&quot;">​</a></h3><p>具体事务会不断增加，若只追逐已显的枝末，便可能失去判断取舍的依据。王弼强调得本以知末，不是取消知识，而是使见闻仍与根本相连。</p><h3 id="用-今天怎样借用塞兑与归明" tabindex="-1">用：今天怎样借用塞兑与归明？ <a class="header-anchor" href="#用-今天怎样借用塞兑与归明" aria-label="Permalink to &quot;用：今天怎样借用塞兑与归明？&quot;">​</a></h3><p>可以检查哪些刺激与事务正在制造无尽追逐，也检查自己的明察是否变成控制他人的冲动。必要的信息、沟通与责任应保留，所收住的是逐欲和妄察。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>处理事务时也追问所由。</strong> 面对反复出现的问题，不只增加补救动作，也回看它从何处生成。问原与济事可以配合，不能只让枝末继续扩张。</p><p><strong>用理解帮助人，而不急于掌控人。</strong> 清楚解释问题有助于去迷，反复窥察、逼迫他人表态却可能损害信任。用光归明可启发这种分辨。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是在用所知帮助自己守住根本，还是只增加更多要追逐的事项？哪些明察已经变成了不必要的窥察与控制？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 013a–013b 电子录文核对。既得其母、以知其子，录文作既知其母、复知其子；没身不殆在录文作没其不殆，均列明而不混改。</li><li>本站是为袭常，录文作是谓习常，王注仅释道之常也；本站采用承守常道的读法，不伪作袭字的直接古注。</li><li>兑按欲求门户的孔窍取象，济按助成事务，勤沿劳倦义，强沿强健义并覆盖本页读音为 qiáng；明另列洞察细微而不苛察义。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，013a–013b</a>。</p>',15))])}}});export{f as __pageData,_ as default};
